import sys
from collections import Counter

def main():
    input_data = sys.stdin.buffer.read().split()
    if not input_data:
        return

    idx = 0
    n = int(input_data[idx])
    idx += 1

    dice = []
    for _ in range(n):
        k = int(input_data[idx])
        idx += 1
        faces = input_data[idx:idx+k]
        idx += k
        c = Counter(faces)
        dice.append((k, c))

    best = 0.0
    for i in range(n):
        ki, ci = dice[i]
        for j in range(i+1, n):
            kj, cj = dice[j]

            if len(ci) > len(cj):
                small_c, large_c = cj, ci
            else:
                small_c, large_c = ci, cj

            s = 0
            for face, cnt in small_c.items():
                if face in large_c:
                    s += cnt * large_c[face]

            p = s / (ki * kj)
            if p > best:
                best = p

    print(f"{best:.15f}")

if __name__ == '__main__':
    main()
